$courses-v26-palette: (
    'ug': (
        $color-brand-primary,
        $color-brand-secondary,
        $color-bg--dark,
        $color-bg,
    ),
    'pgt': (
        $color-blue50,
        $color-blue60,
        $color-blue70,
        $color-blue80,
    ),
    'pgr': (
        $color-orange50,
        $color-orange60,
        $color-orange70,
        $color-orange80,
    ),
);

.courses-v26 {
    .chart-row__items__chart__row__title {
        margin-bottom: $measure--basic;
    }

    .chart-row__items__chart__row {
        @include media('>small') {
            display: flex;
            flex-direction: row;
            align-content: center;
            column-gap: $measure--basic;
        }
    }

    .chart-row__items__chart__row__legend {
        @include media('>small') {
            width: 80%;
        }
    }

    .chart-row__items__chart__row__legend__description {
        margin-bottom: $measure--basic;
    }

    .chart-row__items__chart__row__legend__item {
        text-align: left;
        padding-left: 1rem;

        &:not(:last-child) {
            &:after {
                content: initial;
                position: initial;
                bottom: initial;
                left: initial;
                background: initial;
                height: initial;
                width: initial;
            }
        }
    }

    .chart-row__items__chart__row__graph {
        padding-bottom: $measure--basic;

        @include media('>small') {
            width: 20%;
        }
    }

    #employability {
        .chart-row__items__chart {
            width: 100%;
        }

        .chart-row__items__chart__row {
            @include media('>small') {
                flex-direction: row;
            }
        }

        .chart-row__items__chart__row__graph {
            width: 20%;
        }

        .chart-row__items__chart__row__legend {
            width: 80%;
        }

        .chart-row__items__chart__row__legend__item {
            text-align: left;
            padding-left: $measure--basic;
            margin-bottom: $measure--basic;

            @include gammatype();
        }

        .chart-row__items__chart__row__legend__item__label {
            @include alphatype();
            color: $color-gray6;

            margin-left: initial;
        }
    }
}

@each $level, $color in $courses-v26-palette {
    $firstColor: nth($color, 1);
    $secColor: nth($color, 2);
    $thirdColor: nth($color, 3);
    $fourthColor: nth($color, 4);

    .#{$level}-courses-v26 {
        .chart-row__items__chart {
            path {
                &:nth-child(1) {
                    stroke: $firstColor;
                }

                &:nth-child(2) {
                    stroke: $secColor;
                }

                &:nth-child(3) {
                    stroke: $thirdColor;
                }

                &:nth-child(4) {
                    stroke: $fourthColor;
                }
            }

            .chart-row__items__chart__row__legend__description
                ~ .chart-row__items__chart__row__legend__item {
                &:nth-child(2) {
                    .fa.fa-circle {
                        color: $firstColor;
                    }
                }

                &:nth-child(3) {
                    .fa.fa-circle {
                        color: $secColor;
                    }
                }

                &:nth-child(4) {
                    .fa.fa-circle {
                        color: $thirdColor;
                    }
                }

                &:nth-child(5) {
                    .fa.fa-circle {
                        color: $fourthColor;
                    }
                }
            }

            .chart-row__items__chart__row__legend__item {
                &:nth-child(1) {
                    .fa.fa-circle {
                        color: $firstColor;
                    }
                }

                &:nth-child(2) {
                    .fa.fa-circle {
                        color: $secColor;
                    }
                }

                &:nth-child(3) {
                    .fa.fa-circle {
                        color: $thirdColor;
                    }
                }

                &:nth-child(3) {
                    .fa.fa-circle {
                        color: $fourthColor;
                    }
                }
            }
        }

        #employability {
            .chart-row__items__chart__row__legend__description
                ~ .chart-row__items__chart__row__legend__item {
                &:nth-child(2) {
                    border-left: $measure--half solid $firstColor;
                }

                &:nth-child(3) {
                    border-left: $measure--half solid $secColor;
                }

                &:nth-child(4) {
                    border-left: $measure--half solid $thirdColor;
                }

                &:nth-child(5) {
                    border-left: $measure--half solid $fourthColor;
                }
            }
        }
    }
}
